# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
            return out
    return out

# region: gather
def gather(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: digest
def digest(xs, offset=4):
    return [v + offset for v in xs]

# region: emit
def emit(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return render(fold(emit(digest(gather(sift(raw))))))

